```javascript
function createCharacterNode(character) {
  return {
    character,
    left: null,
    right: null
  };
}

function constructBinaryTree(string) {
  if (string.length === 0) {
    return null;
  }

  var root = createCharacterNode(string[0]);
  var queue = [root];
  var index = 1;

  while(index < string.length) {
    var currentNode = queue.shift();
    if(index < string.length) {
      currentNode.left = createCharacterNode(string[index++]);
      queue.push(currentNode.left);
    }
    if(index < string.length) {
      currentNode.right = createCharacterNode(string[index++]);
      queue.push(currentNode.right);
    }
  }

  return root;
}
```

The `constructBinaryTree` function takes string as parameter and constructs a binary tree where each node is a character from the string.

