def findPivotIndex(nums):
    start, end = 0, len(nums) - 1

    while start <= end:
        mid = (start + end) // 2

        if mid < end and nums[mid] > nums[mid + 1]:
            return mid
        if mid > start and nums[mid] < nums[mid - 1]:
