import hashlib
from typing import Union, List, Tuple

class OptionsFingerprinter:
    @staticmethod
    def fingerprint(data: Union[List[int], Tuple[str, str]]) -> str:
        if isinstance(data, list):
            return OptionsFingerprinter._fingerprint_list(data)
        elif isinstance(data, tuple) and len(data) == 2 and isinstance(data[0], str) and isinstance(data[1], str):
            return OptionsFingerprinter._fingerprint_file(data[0], data[1])
        else:
            raise ValueError("Invalid input type for fingerprinting")

    @staticmethod
    def _fingerprint_list(data: List[int]) -> str:
        fingerprint = hashlib.sha256(str(data).encode()).hexdigest()
        return fingerprint

    @staticmethod
    def _fingerprint_file(file_path: str, content: str) -> str:
        file_content = f"{file_path}:{content}"
        fingerprint = hashlib.sha256(file_content.encode()).hexdigest()
        return fingerprint

