def final_stack_state(operations):
    stack = []
    for op in operations:
        if op.startswith("PUSH"):
            _, num = op.split()
            stack.append(int(num))
        elif op == "POP":
            stack.pop()
        elif op.startswith("INC"):
            _, y, z = op.split()
            y, z = int(y), int(z)
            for i in range(min(y, len(stack))):
                stack[i] += z
    return stack
